def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_pressures = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                opp_pressures.append((bid, opp.get('hp', 0), opp.get('budget', 0), opp.get('no_water_days', 0)))

    if budget <= 0:
        return 0.0

    alive_count = len(alive)
    if alive_count == 0:
        return float(min(budget, 18.0 if hp > 3 else 42.0))

    scarcity = 1.0 - ((supply - 15.0) / 10.0)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    my_urgency = 0.0
    if hp <= 2:
        my_urgency += 0.75
    elif hp <= 4:
        my_urgency += 0.4
    if no_water_days >= 2:
        my_urgency += 0.5
    elif no_water_days >= 1:
        my_urgency += 0.2
    if day >= 8:
        my_urgency += 0.1

    high_threat = 0.0
    medium_threat = 0.0
    for bid, ohp, obudget, onwd in opp_pressures:
        threat = 0.0
        if bid >= 105:
            threat += 1.0
        elif bid >= 80:
            threat += 0.6
        elif bid >= 50:
            threat += 0.3
        if ohp <= 3:
            threat += 0.25
        if onwd >= 1:
            threat += 0.2
        if obudget < 60:
            threat -= 0.15
        if threat >= 1.0:
            high_threat += 1.0
        elif threat >= 0.45:
            medium_threat += 1.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if supply >= 23:
        base = 16.0
    elif supply >= 21:
        base = 22.0
    elif supply >= 19:
        base = 31.0
    elif supply >= 17:
        base = 42.0
    else:
        base = 56.0

    if highest_prev >= 110:
        if my_urgency < 0.45 and supply >= 18:
            base = min(base, 24.0)
        else:
            base = max(base, 68.0)
    elif highest_prev >= 90:
        if my_urgency < 0.35 and supply >= 20:
            base = min(base, 26.0)
        else:
            base = max(base, 58.0)
    elif highest_prev >= 70:
        base = max(base, min(62.0, highest_prev + 2.0))
    elif highest_prev > 0:
        base = max(base, min(55.0, avg_prev + 3.0))

    base += scarcity * 10.0
    base += my_urgency * 22.0
    base += high_threat * 4.0
    base += medium_threat * 2.0

    if hp <= 2 or no_water_days >= 2:
        base = max(base, 78.0 if supply <= 18 else 66.0)
    elif hp <= 4 and supply <= 17:
        base = max(base, 62.0)

    if budget < 50:
        base = min(base, budget)
    elif budget < 120:
        base = min(base, 0.72 * budget)
    else:
        reserve_factor = 0.22 + 0.08 * scarcity
        if hp <= 3:
            reserve_factor += 0.12
        cap = budget * reserve_factor
        if cap < 28.0:
            cap = 28.0
        base = min(base, cap)

    if day == 1 and supply >= 21 and hp >= 8:
        base = min(base, 20.0)

    if base < 0.0:
        base = 0.0
    if base > budget:
        base = budget

    return float(round(base, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_active_players = len(alive_opponents) + 1 

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid * 1.05) 
        else:
            base_bid = max(base_bid, average_prev_bid * 1.1) 
    else:
        base_bid = DAILY_SALARY * 0.6

    supply_per_player = day_context['supply'] / num_active_players

    if supply_per_player >= WATER_REQ * 1.5: 
        base_bid *= 0.8
    elif supply_per_player < WATER_REQ * 1.1: 
        base_bid *= 1.2

    total_demand = WATER_REQ * num_active_players
    if day_context['supply'] < total_demand: 
        base_bid = max(base_bid, DAILY_SALARY * 0.7) 

    if day_context['day'] >= EPISODE_DAYS - 2 and my_status['budget'] > DAILY_SALARY * 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_status['budget'], max(0.0, base_bid))

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        final_bid = min(my_status['budget'], max(final_bid, DAILY_SALARY * 0.95))

    return final_bid

